class Solution {
public:
    double findMaxAverage(vector<int>& nums, int k) {
        int sum = 0;
        for (int r = 0; r < k; r++) sum += nums[r];
        int best = sum;
        for (int r = k; r < (int)nums.size(); r++) {
            int l = r - k + 1;
            sum += nums[r] - nums[l - 1];
            best = max(best, sum);
        }
        return (double)best / k;
    }
};
